  (uuid_generate_v4(), 'handmade-mohave-turquoise-ring-925-sterling-silver-boho-statement-jewelry-for-wo', '4512646877', 'https://www.etsy.com/listing/4512646877/handmade-mohave-turquoise-ring-925?click_key=EuslJBqaIzsPErOOexVCqDwaaz29%3ALTe903339e2f715606abcf59f15801d56d2069bfd7&click_sum=f228f5ee&ls=a&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=turquoise+jewelry&ref=search_grid-37502-17-9&sr_prefetch=1&pf_from=search&pro=1&frs=1',
