  (uuid_generate_v4(), 'reclaimed-wood-earrings-with-recycled-copper-and-turquoise-chip-inlay', '906777315', 'https://www.etsy.com/listing/906777315/reclaimed-wood-earrings-with-recycled?click_key=EuslJBqaIzsPErOOexVCqDwaaz29%3ALTb977f4b0370182d711dd262874aead04d21c85ea&click_sum=7148664e&ls=a&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=turquoise+jewelry&ref=search_grid-1019172-17-4&sr_prefetch=1&pf_from=search&pop=1&sts=1',
